'use strict';
let masterCampaigns=[],masterCharacters=[],masterMembers=[],masterUsers=[];
const masterName=r=>r.data.nickname||r.data.name||'Без имени';
const accountName=u=>u.login||u.id;
async function masterLoad(){if(!portalMaster)throw Error('Нужны права мастера');[masterCampaigns,masterCharacters,masterMembers]=await Promise.all([C.campaigns(),C.list(),C.memberships()]);}
async function masterReady(){await save();if(dirty||saving)throw Error('Дождись сохранения карточки');clearTimeout(saveTimer);cloudRecord=null;}
function masterNavigation(){return '<div class="master-tabs"><button id="master-campaigns">Кампании</button><button id="master-accounts">Учётные записи</button><button id="master-catalog">Справочник</button></div>';}
function bindMasterNavigation(){ $('#master-campaigns').onclick=showCampaigns;$('#master-accounts').onclick=showAccounts;$('#master-catalog').onclick=showCatalogAdmin;}
async function showMasterHub(){try{await masterReady();portalView='master';portalShell('Терминал мастера.','Кампании, игроки и истории — под твоим контролем.',masterNavigation()+'<div class="role-grid"><button id="hub-campaigns" class="role-card"><span class="eyebrow">01 / ИСТОРИИ</span><strong>Кампании</strong><p>Обложки, состав персонажей и отдельный журнал каждой сессии.</p><span class="role-arrow">Выбрать кампанию ↗</span></button><button id="hub-accounts" class="role-card"><span class="eyebrow">02 / ИГРОКИ</span><strong>Учётные записи</strong><p>Все пользователи, их персонажи и назначение в кампании.</p><span class="role-arrow">Управлять аккаунтами ↗</span></button></div>');bindMasterNavigation();$('#hub-campaigns').onclick=showCampaigns;$('#hub-accounts').onclick=showAccounts;}catch(e){portalError(e);}}
async function showCampaigns(){try{await masterLoad();portalView='campaigns';portalShell('Кампании.','У каждой истории — своя команда и журнал сессий.',masterNavigation()+`<div class="library-toolbar"><button id="new-campaign" class="yellow">+ Создать кампанию</button><button id="unassigned">Без кампании (${masterCharacters.filter(r=>!masterMembers.some(m=>m.character_id===r.id)).length})</button></div><div class="campaign-grid">${masterCampaigns.map(c=>`<button class="campaign-tile" data-campaign="${c.id}">${c.cover?`<img src="${esc(c.cover)}" alt="Обложка ${esc(c.name)}">`:'<div class="campaign-cover-placeholder">WD / CAMPAIGN</div>'}<div><span class="eyebrow">${masterMembers.filter(m=>m.campaign_id===c.id).length} ПЕРСОНАЖЕЙ</span><h2>${esc(c.name)}</h2><p>${esc(c.description.slice(0,200))}</p><span class="role-arrow">Открыть кампанию ↗</span></div></button>`).join('')||'<p class="empty-library">Кампаний пока нет. Создай первую историю.</p>'}</div>`);bindMasterNavigation();$('#new-campaign').onclick=()=>editCampaign();$('#unassigned').onclick=()=>showCampaign(null);document.querySelectorAll('[data-campaign]').forEach(b=>b.onclick=()=>showCampaign(b.dataset.campaign));}catch(e){portalError(e);}}
function masterCard(r){return `<article class="master-character"><div><span class="eyebrow">ПЕРСОНАЖ</span><h3>${esc(masterName(r))}</h3><p>${esc((r.data.bio||'История ещё не написана.').slice(0,160))}</p></div><button data-master-open="${r.id}">Открыть карточку ↗</button><label class="field"><span>Кампания</span><select data-assign="${r.id}" aria-label="Кампания: ${esc(masterName(r))}"><option value="">Без кампании</option>${masterCampaigns.map(c=>`<option value="${c.id}" ${masterMembers.some(m=>m.character_id===r.id&&m.campaign_id===c.id)?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label><button class="danger" data-master-delete="${r.id}">Удалить персонажа</button></article>`;}
function bindMasterCards(){document.querySelectorAll('[data-master-open]').forEach(b=>b.onclick=()=>openCard(b.dataset.masterOpen).catch(portalError));document.querySelectorAll('[data-master-delete]').forEach(b=>b.onclick=()=>confirmDeleteCharacter(masterCharacters.find(r=>r.id===b.dataset.masterDelete)));document.querySelectorAll('[data-assign]').forEach(s=>s.onchange=async()=>{const old=masterMembers.find(m=>m.character_id===s.dataset.assign)?.campaign_id||'';s.disabled=true;try{await C.assignCampaign(s.dataset.assign,s.value||null);masterMembers=masterMembers.filter(m=>m.character_id!==s.dataset.assign);if(s.value)masterMembers.push({character_id:s.dataset.assign,campaign_id:s.value});notify('Кампания назначена');}catch(e){s.value=old;portalError(e);}finally{s.disabled=false;}});}
async function showCampaign(id){try{await masterLoad();const c=masterCampaigns.find(c=>c.id===id);if(id&&!c)throw Error('Кампания удалена');const sessions=id?await C.sessions(id):[];portalView='campaign';portalCampaignId=id;const rows=masterCharacters.filter(r=>id?masterMembers.some(m=>m.character_id===r.id&&m.campaign_id===id):!masterMembers.some(m=>m.character_id===r.id));portalShell(esc(c?.name||'Без кампании'),esc(c?.description||'Назначь персонажей в кампании через выпадающий список.'),masterNavigation()+`${c?.cover?`<div class="campaign-banner"><img class="campaign-banner-blur" src="${esc(c.cover)}" alt="" aria-hidden="true"><img class="campaign-banner-image" src="${esc(c.cover)}" alt="Обложка кампании"></div>`:''}${c?'<div class="library-toolbar"><button id="edit-campaign">Изменить кампанию</button><button id="add-session" class="yellow">+ Заметка сессии</button><button id="delete-campaign" class="danger">Удалить кампанию</button></div>':''}<h2 class="master-section-title">Персонажи · ${rows.length}</h2><div class="master-character-grid">${rows.map(masterCard).join('')||'<p class="empty-library">Персонажей пока нет. Назначь их в разделе «Учётные записи».</p>'}</div>${c?`<h2 class="master-section-title">Журнал сессий · ${sessions.length}</h2><div class="session-list">${sessions.map(s=>`<details class="session-note"><summary><span>${esc(s.title)}</span><small>${esc(s.session_date||'Без даты')}</small></summary><p>${esc(s.notes)}</p><button data-session="${s.id}">Редактировать</button><button data-session-delete="${s.id}" class="danger">Удалить заметку</button></details>`).join('')||'<p class="hint">Добавляй отдельную заметку для каждой игровой сессии.</p>'}</div>`:''}`);bindMasterNavigation();bindMasterCards();if(c){$('#edit-campaign').onclick=()=>editCampaign(c);$('#add-session').onclick=()=>editSession(c);$('#delete-campaign').onclick=()=>masterConfirm('Удалить кампанию?',`Заметки сессий будут удалены. Персонажи останутся в разделе «Без кампании».`,async()=>{await C.deleteMaster('campaigns',c);await showCampaigns();});document.querySelectorAll('[data-session]').forEach(b=>b.onclick=()=>editSession(c,sessions.find(s=>s.id===b.dataset.session)));document.querySelectorAll('[data-session-delete]').forEach(b=>b.onclick=()=>masterConfirm('Удалить заметку сессии?','Это действие нельзя отменить.',async()=>{await C.deleteMaster('campaign_sessions',sessions.find(s=>s.id===b.dataset.sessionDelete));await showCampaign(id);}));}}catch(e){portalError(e);}}
function masterConfirm(title,description,action){modal(title,`<p>${esc(description)}</p><div class="library-toolbar"><button id="master-cancel">Отмена</button><button id="master-confirm" class="danger">Подтвердить удаление</button></div>`);$('#master-cancel').onclick=closeModal;$('#master-cancel').focus();$('#master-confirm').onclick=async()=>{const b=$('#master-confirm');b.disabled=true;try{await action();closeModal();}catch(e){error(e);b.disabled=false;}};}
async function resizeCampaignCover(file){return window.ND_PORTRAIT.crop(file,{kind:'campaign'});}
function editCampaign(c){let cover=c?.cover||'',pending=false;modal(c?'Редактирование кампании':'Новая кампания',`<form id="campaign-form"><label class="field"><span>Название</span><input name="title" required maxlength="200" value="${esc(c?.name||'')}"></label><label class="field"><span>Описание</span><textarea name="description" maxlength="20000" rows="5">${esc(c?.description||'')}</textarea></label><label class="field"><span>Горизонтальная обложка · до 10 МБ</span><input id="campaign-cover" type="file" accept="image/jpeg,image/png,image/webp"></label><div id="cover-preview">${cover?`<img class="campaign-hero" src="${esc(cover)}" alt="Обложка">`:''}</div><button type="button" id="remove-cover">Убрать обложку</button><button type="submit" class="yellow">Сохранить</button></form>`);$('#remove-cover').onclick=()=>{cover='';$('#cover-preview').innerHTML='';};$('#campaign-cover').onchange=async e=>{const file=e.target.files[0];if(!file)return;pending=true;try{const cropped=await resizeCampaignCover(file);if(!cropped)return;cover=cropped;$('#cover-preview').innerHTML=`<img class="campaign-hero" src="${cover}" alt="Обложка">`;}catch(e){error(e);}finally{pending=false;e.target.value='';}};$('#campaign-form').onsubmit=async e=>{e.preventDefault();if(pending)return;const f=e.currentTarget,b=f.querySelector('[type=submit]');b.disabled=true;try{const row=await C.writeMaster('campaigns',{name:f.elements.title.value.trim(),description:f.description.value,cover},c);closeModal();await showCampaign(row.id);}catch(e){error(e);b.disabled=false;}};}
function editSession(c,s){modal(s?'Редактирование сессии':'Новая сессия',`<form id="session-form"><label class="field"><span>Название сессии</span><input name="title" required maxlength="200" value="${esc(s?.title||'')}"></label><label class="field"><span>Дата</span><input name="date" type="date" value="${esc(s?.session_date||'')}"></label><label class="field"><span>Заметки мастера</span><textarea name="notes" rows="12" maxlength="50000">${esc(s?.notes||'')}</textarea></label><button class="yellow" type="submit">Сохранить заметку</button></form>`);$('#session-form').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,b=f.querySelector('button');b.disabled=true;try{await C.writeMaster('campaign_sessions',{campaign_id:c.id,title:f.elements.title.value.trim(),session_date:f.date.value||null,notes:f.notes.value},s);closeModal();await showCampaign(c.id);}catch(e){error(e);b.disabled=false;}};}
async function showAccounts(){try{await masterLoad();masterUsers=await C.masterAccounts();portalView='accounts';portalShell('Учётные записи.','Раскрой аккаунт, чтобы открыть персонажей и назначить им кампанию.',masterNavigation()+`<label class="field"><span>Поиск по логину или имени персонажа</span><input id="account-search" type="search" placeholder="Найти игрока…"></label><div id="accounts-list"></div>`);bindMasterNavigation();renderAccounts();$('#account-search').oninput=renderAccounts;}catch(e){portalError(e);}}
function renderAccounts(){const query=$('#account-search').value.toLowerCase();$('#accounts-list').innerHTML=masterUsers.filter(u=>accountName(u).toLowerCase().includes(query)||masterCharacters.some(r=>r.owner_id===u.id&&masterName(r).toLowerCase().includes(query))).map(u=>{const rows=masterCharacters.filter(r=>r.owner_id===u.id);return `<details class="account-entry" ${query?'open':''}><summary><span><strong>${esc(accountName(u))}</strong><small>${u.is_master?'Мастер · защищённый аккаунт':'Игрок'} · ${rows.length} персонажей</small></span><span class="account-expand">Раскрыть</span></summary><div class="account-content"><div class="master-character-grid">${rows.map(masterCard).join('')||'<p>Персонажей пока нет.</p>'}</div><div class="account-footer"><span class="micro">Регистрация: ${new Date(u.created_at).toLocaleDateString('ru-RU')}</span>${u.is_master?'':`<button data-delete-account="${u.id}" class="danger">Удалить аккаунт со всем содержимым</button>`}</div></div></details>`;}).join('')||'<p>Ничего не найдено.</p>';bindMasterCards();document.querySelectorAll('[data-delete-account]').forEach(b=>b.onclick=()=>confirmAccountDeletion(masterUsers.find(u=>u.id===b.dataset.deleteAccount)));}
function confirmAccountDeletion(u){const count=masterCharacters.filter(r=>r.owner_id===u.id).length;modal('Удалить учётную запись?',`<p>Аккаунт <strong>${esc(accountName(u))}</strong> и все его персонажи (${count}), фотографии, инвентарь и заметки будут удалены без восстановления. Кампании и заметки мастера останутся.</p><label class="field"><span>Для подтверждения введи логин: ${esc(accountName(u))}</span><input id="delete-account-login" autocomplete="off"></label><button id="cancel-account-delete">Отмена</button><button id="delete-account-final" class="danger" disabled>Удалить аккаунт и содержимое</button>`);$('#cancel-account-delete').onclick=closeModal;$('#delete-account-login').oninput=e=>{$('#delete-account-final').disabled=e.target.value!==accountName(u);};$('#delete-account-final').onclick=async()=>{const b=$('#delete-account-final');b.disabled=true;try{const ids=await C.deleteAccount(u.id,$('#delete-account-login').value);for(const id of ids){purgeDeletedCard(id);try{localStorage.setItem('nd-deleted-card',id);localStorage.removeItem('nd-deleted-card');}catch{}}closeModal();await showAccounts();notify('Аккаунт и персонажи удалены');}catch(e){error(e);b.disabled=false;}};}
